SELECT post_tag.post_id, tag.id AS tag_id, tag.name, tag.slug FROM cms_post_tag post_tag JOIN cms_tag tag ON tag.id = post_tag.tag_id WHERE post_tag.post_id IN
#{postId}
ORDER BY post_tag.post_id, tag.name, tag.id

SELECT COUNT(*)
FROM cms_post
WHERE status = #{status}

SELECT EXISTS(
    SELECT 1
    FROM cms_post
    WHERE slug = #{slug}


        AND id <> #{excludeId}

)
